const http=require('http'),fs=require('fs'),path=require('path');const base=process.cwd();
http.createServer((req,res)=>{let p;try{p=decodeURIComponent(req.url.split('?')[0]);}catch{res.writeHead(400).end();return;}const file=path.resolve(base,'.'+(p==='/'?'/index.html':p));if(!file.startsWith(base+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404).end();return;}const type={'.html':'text/html','.css':'text/css','.js':'text/javascript','.png':'image/png','.svg':'image/svg+xml'}[path.extname(file)]||'application/octet-stream';res.writeHead(200,{'Content-Type':type,'Cache-Control':'no-store'});fs.createReadStream(file).pipe(res);}).listen(4173,'127.0.0.1',()=>console.log('Preview http://127.0.0.1:4173'));
